out = {}
for k, s in src.items():
    p, n, q, ans, r, x = D[k]
    assert len(p) == len(s['phrases']) and len(n) == len(s['nouns']), k
    rec = list(p) + ([x] if x else []) + [r]
    assert len(rec) == len(s['recall']), (k, rec)
    out[k] = {'phrases': p, 'nouns': n, 'question': q, 'answer': ans, 'captions': {}, 'recall': rec}
json.dump(out, open(f'{H}/tr/b001/de/ua.json', 'w'), ensure_ascii=False, indent=1)
